                version=np.lib.format.read_magic(stream);assert version in [(1,0),(2,0)];shape,order,dtype=(np.lib.format.read_array_header_1_0 if version==(1,0) else np.lib.format.read_array_header_2_0)(stream);assert not dtype.hasobject;size=math.prod(shape)*dtype.itemsize;observed=0 # Object arrays and ambiguous payload sizes are not admitted.
